// DonutOS service worker: makes the web version work offline and delivers updates.
//
// precache-manifest.js (generated by `npm run build:precache`) lists every file in the
// app plus a content hash. When any file changes, the hash changes, the browser sees a new
// service worker, downloads the new files in the background, and DonutOS offers a restart.

importScripts('./precache-manifest.js');

const { version, files } = self.DONUT_PRECACHE;
const CACHE = `donutos-${version}`;
const BASE = new URL('./', self.location).href;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // cache: 'reload' bypasses the HTTP cache so we never precache stale files.
    await cache.addAll(files.map((f) => new Request(new URL(f, BASE), { cache: 'reload' })));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith('donutos-') && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // weather API, web pages: straight to the network
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const key = req.mode === 'navigate' && url.pathname.endsWith('/') ? new URL('index.html', url).href : req;
    const hit = await cache.match(key, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch {
      if (req.mode === 'navigate') return (await cache.match(new URL('index.html', BASE).href)) || Response.error();
      return Response.error();
    }
  })());
});
